// Recipe viewer mod (not 1.7.10): the enumerable recipe table behind the item list.
//
// Every crafting entry is checked through the live craftingResult (survival.js) when the table is built, and its output is
// what that call returns, so the viewer shows what this build crafts, not a guess:
//   * native-recipes.js: the native 1.7.10 CraftingManager registry in browser ids (generated by tools/jei-recipes.mjs);
//   * survival.js RECIPES and SHAPELESS, the enumerable live tables (most of them repeat a native entry and are dropped);
//   * worked examples of the dynamic handlers (tool repair, dyed leather, fireworks, book copying);
//   * recipe lists other opt-in mods register (registerRecipeSource);
// smelting comes from SMELTING through smeltingResult, fuel from FUELS through burnTime.
//
// Entry shapes:
//   { category: "crafting", shapeless, width, height, slots, output, note? }
//      slots: shaped, the 3x3 grid row-major; shapeless, the ingredients. Each slot is null or [[id, damage], ...], the
//      alternatives the grid accepts there (the viewer cycles them); a dynamic example's slot may carry a full stack instead.
//   { category: "smelting", slots: [[[id, 0]]], output, xp }  (FurnaceRecipes ignore the input's damage)
//   { category: "fuel", slots: [[[id, 0]]], burn }            (getItemBurnTime ignores the damage)
// Mod sources may also supply { category: "smithing", station, slots, craft(slots) -> output }; ingredients carry their
// full counts as stack alternatives, and the source's live smithing function verifies the result while building the table.
import { ITEMS, RECIPES, SHAPELESS, SMELTING, FUELS, craftingResult, smeltingResult, burnTime } from "../../survival.js";
import { makeStack } from "../../inventory.js";
import { smeltExperience } from "../../experience.js";
import { DYE } from "../../world.js";
import { ITEM_WRITABLE_BOOK, ITEM_WRITTEN_BOOK } from "../../books.js";
import { NATIVE_RECIPES } from "./native-recipes.js";

const sources = new Map();
let table = null;
// fn() -> crafting or smithing entries as above. Mods call this when they turn on; the table is rebuilt on its next use,
// and every entry goes through its live crafting handler.
export function registerRecipeSource(name, fn) {
  if (typeof fn === "function") sources.set(name, fn);
  else sources.delete(name);
  table = null;
}
export const invalidateRecipes = () => { table = null; };

const stackOf = (slot, k = 0) => {
  if (!slot) return null;
  const alt = slot[k % slot.length];
  return Array.isArray(alt) ? makeStack(alt[0], 1, alt[1] | 0) : { ...alt };
};
// The 3x3 grid an entry describes (shapeless ingredients fill it row by row), with alternative k in every slot.
export function entryGrid(entry, k = 0) {
  const cells = Array(9).fill(null);
  entry.slots.forEach((s, i) => (cells[i] = stackOf(s, k)));
  return cells;
}
const outputOf = (s) => ({ ...s, damage: s.damage | 0 });
// Two entries with the same output and the same ingredients are one recipe to a player (a live 1x1 shaped recipe repeats a
// native shapeless one); the first kept wins, so native entries come first.
const key = (e) => JSON.stringify([e.category, e.station, e.slots.filter(Boolean).map((s) => JSON.stringify(s[0])).sort(), e.output.id, e.output.damage, e.output.count]);

// survival.js RECIPES: id-only patterns (the matcher ignores damage) at the grid's top left.
function liveShaped(r) {
  const slots = Array(9).fill(null);
  for (let y = 0; y < r.height; y++) for (let x = 0; x < r.width; x++) {
    const id = r.pattern[y * r.width + x];
    if (id) slots[y * 3 + x] = [[id, 0]];
  }
  return { shapeless: false, width: r.width, height: r.height, slots };
}
const liveShapeless = (r) => ({ shapeless: true, width: 0, height: 0, slots: r.ingredients.map((i) => [[i.id, i.damage ?? 0]]) });

// Worked examples of the dynamic handlers (CraftingManager's special recipes and the repair rule), one grid each.
function dynamicExamples() {
  const pick = 102, max = ITEMS[pick]?.durability ?? 250, worn = Math.floor(max * 0.6);
  const book = makeStack(ITEM_WRITTEN_BOOK, 1, 0, undefined, { pages: ["Page 1"], author: "Author", title: "Book" });
  return [
    { note: "Repair", slots: [[makeStack(pick, 1, worn)], [makeStack(pick, 1, worn)]] },
    { note: "Any dye colours the armor", slots: [[[401, 0]], [[DYE, 1], [DYE, 4], [DYE, 2], [DYE, 11]]] },
    { note: "Up to 3 gunpowder: flight 1-3", slots: [[[328, 0]], [[330, 0]]] },
    { note: "Dyes set the colours", slots: [[[330, 0]], [[DYE, 1], [DYE, 4], [DYE, 2], [DYE, 11]]] },
    { note: "Copies a written book", slots: [[book], [[ITEM_WRITABLE_BOOK, 0]]] },
  ].map((e) => ({ ...e, shapeless: true, width: 0, height: 0 }));
}

function build() {
  const crafting = [], smithing = [], seen = new Set();
  const add = (entry, source) => {
    if (!entry?.slots?.length) return;
    let out = null;
    const isSmithing = entry.category === "smithing" && typeof entry.craft === "function" && ITEMS[entry.station];
    try { out = isSmithing ? entry.craft(entry.slots.map((s) => stackOf(s))) : craftingResult(entryGrid(entry), 3); } catch { out = null; }
    if (!out || !ITEMS[out.id]) return;
    const { craft, ...fields } = entry;
    const e = { ...fields, category: isSmithing ? "smithing" : "crafting", output: outputOf(out), source };
    const k = key(e);
    if (seen.has(k)) return;
    seen.add(k);
    (isSmithing ? smithing : crafting).push(e);
  };
  for (const r of NATIVE_RECIPES) add({ shapeless: r.shapeless, width: r.width, height: r.height, slots: r.slots }, "native");
  for (const r of RECIPES) add(liveShaped(r), "live");
  for (const r of SHAPELESS) add(liveShapeless(r), "live");
  for (const [name, fn] of sources) {
    let list = [];
    try { list = fn() ?? []; } catch { list = []; }
    for (const e of list) add(e, "mod:" + name);
  }
  for (const e of dynamicExamples()) add(e, "dynamic");
  const smelting = [];
  for (const id of Object.keys(SMELTING).map(Number).sort((a, b) => a - b)) {
    if (!ITEMS[id]) continue;
    const input = makeStack(id, 1, 0), out = smeltingResult(input);
    if (out && ITEMS[out.id]) smelting.push({ category: "smelting", slots: [[[id, 0]]], output: outputOf(out), xp: smeltExperience(out) });
  }
  const fuel = [];
  for (const id of Object.keys(FUELS).map(Number).sort((a, b) => a - b)) {
    const burn = ITEMS[id] ? burnTime(makeStack(id, 1, 0)) : 0;
    if (burn > 0) fuel.push({ category: "fuel", slots: [[[id, 0]]], burn });
  }
  return { crafting, smithing, smelting, fuel, all: [...crafting, ...smithing, ...smelting, ...fuel] };
}
export const recipeTable = () => (table ??= build());

// Damage that names a different item (dye colours, wool, planks, potions) must match; a tool's damage is wear and never does.
const sameKind = (id, a, b) => (a | 0) === (b | 0) || !!ITEMS[id]?.durability || !!ITEMS[id]?.gun;
const slotHas = (slot, stack) => !!slot?.some((alt) => (Array.isArray(alt) ? alt[0] === stack.id && sameKind(stack.id, alt[1], stack.damage) : alt.id === stack.id && sameKind(stack.id, alt.damage, stack.damage)));
// FurnaceRecipes and getItemBurnTime look at the id only.
const anyDamage = (e) => e.category === "smelting" || e.category === "fuel";

// The entries that make `stack`.
export function recipesFor(stack) {
  if (!stack) return [];
  return recipeTable().all.filter((e) => e.output && e.output.id === stack.id && sameKind(stack.id, e.output.damage, stack.damage));
}
// The entries that take `stack` as an ingredient or fuel.
export function usesOf(stack) {
  if (!stack) return [];
  return recipeTable().all.filter((e) => e.station === stack.id || e.slots.some((s) => (anyDamage(e) ? s?.some((a) => a[0] === stack.id) : slotHas(s, stack))));
}
